const W=eval(load("wttjHelpers"));
async function locationSearch(name){
await W.nav("tab_j","https://www.welcometothejungle.com/fr/jobs-matches");
if(!await W.ev("tab_j","!!document.querySelector('input[name=locations]')?.getBoundingClientRect().height"))await tools.mcp__t3_code__preview_click({tabId:"tab_j",selector:"[data-testid=filter-accordion-location]"});
for(let n=0;n<5;n++){if(!await W.ev("tab_j","!!document.querySelector('[data-testid=location-tag-0] button')"))break;try{await W.ev("tab_j","document.querySelector('[data-testid=location-tag-0] button').click()")}catch{}await W.delay(200);}
await tools.mcp__t3_code__preview_type({tabId:"tab_j",selector:"input[name=locations]",text:name,clear:true});await W.delay(1700);
const options=await W.ev("tab_j","[...document.querySelectorAll('[role=option]')].map(x=>({id:x.id,text:x.innerText}))");text(options.slice(0,2));
if(!options.length)throw Error("No country option");await tools.mcp__t3_code__preview_click({tabId:"tab_j",selector:"#"+options[0].id});await W.delay(700);
const tag=await W.ev("tab_j","[...document.querySelectorAll('[data-testid^=location-tag]')].map(x=>x.innerText)");if(!tag.length)throw Error("Location selection failed");await tools.mcp__t3_code__preview_click({tabId:"tab_j",selector:"[data-testid=filters-save-button]"});await W.delay(2700);store("wttjSearchLocation",name);text(await W.ev("tab_j","document.body.innerText.slice(0,700)"));
}
({locationSearch,W})
